// L?y to�n b? item t? node tru?c
let items = $input.all();

// S?p x?p theo t�n file (1.png < 2.png < 10.png)
items.sort((a, b) => {
  const nameA = a.json.name.toLowerCase();
  const nameB = b.json.name.toLowerCase();
  return nameA.localeCompare(nameB, undefined, { numeric: true });
});

// G?n type (image / video / other)
for (const item of items) {
  const name = item.json.name.toLowerCase();
  if (name.endsWith('.mp4') || name.endsWith('.mov')) {
    item.json.type = 'video';
  } else if (
    name.endsWith('.jpg') ||
    name.endsWith('.jpeg') ||
    name.endsWith('.png') ||
    name.endsWith('.webp')
  ) {
    item.json.type = 'image';
  } else {
    item.json.type = 'other';
  }
}

